import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"API reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md","lastUpdated":1793717423000}'),d={name:"reference/api.md"};function s(i,e,c,n,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API reference&quot;">​</a></h1><p>The API reference is generated from source JSDoc by TypeDoc 0.28 with <code>entryPointStrategy: packages</code> over the four workspaces in <code>typedoc.json</code>. It is written to <code>docs/api/</code> and served next to this site at <code>/docs/api/</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:api</span></span></code></pre></div><p>Do not edit the generated files. Fix the JSDoc in <code>packages/*/src</code> and rerun. <code>treatWarningsAsErrors</code> is on, so an export without documentation, a broken <code>{@link}</code> or a missing git remote fails the build.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Module page</th></tr></thead><tbody><tr><td><code>@kernl/guard</code></td><td><a href="/api/modules/_kernl_guard.html" target="_self"><code>_kernl_guard</code></a></td></tr><tr><td><code>@kernl/messaging</code></td><td><a href="/api/modules/_kernl_messaging.html" target="_self"><code>_kernl_messaging</code></a></td></tr><tr><td><code>@kernl/bridges</code></td><td><a href="/api/modules/_kernl_bridges.html" target="_self"><code>_kernl_bridges</code></a></td></tr><tr><td><code>@kernl/core</code></td><td><a href="/api/modules/_kernl_core.html" target="_self"><code>_kernl_core</code></a></td></tr></tbody></table><p>The <a href="/api/index.html" target="_self">index page</a> lists all four, and the <a href="/api/hierarchy.html" target="_self">hierarchy page</a> shows type relationships across them.</p><h2 id="how-to-read-it" tabindex="-1">How to read it <a class="header-anchor" href="#how-to-read-it" aria-label="Permalink to &quot;How to read it&quot;">​</a></h2><ul><li>Each module page lists its exports by kind: interfaces, type aliases, functions, variables. Every entry has at least one <code>@example</code>.</li><li>Reasons in thrown errors are documented as string literals (<code>denied:…</code>, <code>invalid:…</code>, <code>unavailable:…</code>) on the function that throws them.</li><li>Types imported from <code>@kehto/*</code> or <code>@napplet/core</code> are linked to their names but not expanded; <code>excludeExternals</code> keeps the reference to kernl&#39;s own surface.</li><li>The reference is HTML only. It has no Markdown twin and is not included in <code>llms-full.txt</code>; the <a href="./../packages/">package pages</a> carry the export lists in Markdown for agents.</li></ul><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p><code>scripts/audit-docs.mjs</code> asserts that <code>docs/api/modules/_kernl_&lt;package&gt;.html</code> exists for every <code>packages/*/package.json</code>, that each package page links to it, and that the built docs carry their Markdown twins. It runs as part of <code>pnpm docs:check</code>.</p>',11)])])}const g=a(d,[["render",s]]);export{u as __pageData,g as default};
